import{bQ as e,aL as a,u as r,G as d}from"./chunks/framework.C1gZXFVa.js";const o="/assets/080101.BBj5klGL.png",b=JSON.parse('{"title":"撮合主流程","description":"交易对已开放后，撮合引擎内下单进簿、比价成交、撤单解冻与 Redis/MQ 外发；不含初始化与委托入口校验。","frontmatter":{"title":"撮合主流程","description":"交易对已开放后，撮合引擎内下单进簿、比价成交、撤单解冻与 Redis/MQ 外发；不含初始化与委托入口校验。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070508"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070508"}],["meta",{"property":"og:title","content":"撮合主流程 · TGEX"}],["meta",{"property":"og:description","content":"交易对已开放后，撮合引擎内下单进簿、比价成交、撤单解冻与 Redis/MQ 外发；不含初始化与委托入口校验。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"撮合主流程 · TGEX"}],["meta",{"name":"twitter:description","content":"交易对已开放后，撮合引擎内下单进簿、比价成交、撤单解冻与 Redis/MQ 外发；不含初始化与委托入口校验。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"撮合主流程\\",\\"description\\":\\"交易对已开放后，撮合引擎内下单进簿、比价成交、撤单解冻与 Redis/MQ 外发；不含初始化与委托入口校验。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070508\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070508\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070508.md","filePath":"07.现货手册/05.核心流程/08.撮合主流程.md"}'),s={name:"pages/070508.md"};function n(i,t,h,p,l,g){return a(),r("div",null,[...t[0]||(t[0]=[d('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="撮合主流程" tabindex="-1">撮合主流程 <a class="header-anchor" href="#撮合主流程" aria-label="Permalink to &quot;撮合主流程&quot;">​</a></h1><div class="doc-lead">交易对已开放后，事件入链：下单先冻结建单，再进簿成交或挂剩；撤单则出簿解冻。深度与成交异步外发，Redis 增量异步落库。</div><p align="center"><img src="'+o+'" alt="撮合主流程"></p><p>本文假定该交易对已完成初始化并开放接单；从「事件已进入撮合处理链」写起。委托侧下单入口见<a href="/pages/070502">下单主流程</a>，撤单入口见<a href="/pages/070503">撤单主流程</a>；装交易对与恢复盘口见<a href="/pages/070505">撮合初始化链路</a>。下文按上图节点展开。</p><h2 id="_1-事件进入撮合处理链" tabindex="-1">1. 事件进入撮合处理链 <a class="header-anchor" href="#_1-事件进入撮合处理链" aria-label="Permalink to &quot;1. 事件进入撮合处理链&quot;">​</a></h2><p>同交易对事件串行投入全局通道。运行时主要两类：</p><table tabindex="0"><thead><tr><th>类型</th><th>图上走哪一支</th></tr></thead><tbody><tr><td>下单</td><td>左支：冻结建单 → 进簿 → 成交循环 → 挂剩或完全成交</td></tr><tr><td>撤单</td><td>右支：出簿 → 解冻 → 委托已撤销</td></tr></tbody></table><p>两支在图末汇合，再走消息外发与异步落库。上游（委托侧调撮合）同步等待的成功，通常表示<strong>下单支的冻结建单已成功</strong>，<strong>不</strong>表示已经全部成交；进簿与成交仍在同链继续。</p><h2 id="bookkeeping" tabindex="-1">2. 下单：冻结并写委托热数据 <a class="header-anchor" href="#bookkeeping" aria-label="Permalink to &quot;2. 下单：冻结并写委托热数据 {#bookkeeping}&quot;">​</a></h2><p>这一步对应图上的「冻结并写委托热数据 + Redis 缓冲」。</p><p>先记住结论：<strong>钱先被系统占用，委托先记下来；但这时还没有挂到盘口，也还没有和任何人成交。</strong><br> 所以接口若在这一步就返回成功，多半只表示「下单已被受理、资金已占用」，不表示已经全部成交。</p><p>同一交易对里，处理顺序固定是两步：先完成本节，再进入下一节「进订单簿」。本节失败，就不会进盘口，也不会告诉上游成功。</p><h3 id="按顺序做什么" tabindex="-1">按顺序做什么 <a class="header-anchor" href="#按顺序做什么" aria-label="Permalink to &quot;按顺序做什么&quot;">​</a></h3><p><strong>1.算该冻哪个币、冻多少</strong></p><table tabindex="0"><thead><tr><th>方向</th><th>冻什么</th><th>怎么算（教学）</th></tr></thead><tbody><tr><td>买</td><td>计价币（如 USDT）</td><td>按这单要付的计价金额占用</td></tr><tr><td>卖</td><td>基础币（如 BTC）</td><td>按这单要卖的数量占用</td></tr></tbody></table><p>例：买入 0.01 BTC、价 60,000 → 大约冻 600 USDT。钱仍在该用户自己账户里，只是从「可用」变成「冻结」，<strong>不会在这一步划给卖方</strong>。手续费一般在后面成交时再扣。</p><p><strong>2.在撮合内存里：可用 → 冻结</strong></p><p>改的是撮合进程里的<a href="/pages/070802">用户币币账户缓存</a>（按用户 × 币种存的那条内存钱包）。运行中以这份为准：够不够、能不能挂单，都先看这里。该钱包上如何校验、减可用、加冻结、记流水，见缓存文档<a href="/pages/070802#total-to-frozen">增量：可用 → 冻结</a>；此处只记结论：</p><ul><li>同一用户、同一币种内部占用，不是转给别人。</li><li>成功才继续写 Redis / 热委托；失败 → <strong>整笔失败</strong>，不进盘口。</li></ul><p><strong>3.往 Redis 记一份「本笔发生了什么」</strong></p><p>不是把整张账户缓存搬到 Redis，也不是改完余额就改以 Redis 为准。 只是把<strong>这一笔动过的内容</strong>旁路记出去，例如：</p><ul><li>账户变动结果（含变动后的钱包快照）</li><li>委托当前内容（以及事件相关记录）</li></ul><p>用途主要是：进程挂了还能恢复、后台再慢慢刷进 MySQL。下单热路径判断余额时，仍然看撮合内存，不拿这份 Redis 当裁判。</p><p><strong>4.写入委托热数据</strong></p><p>把这张单写进<a href="/pages/070803">委托热数据缓存</a>（按委托号等索引）。<br> 此时状态一般是「未成交」，剩余量 = 下单量。<br> 注意：热数据里「有这张单」≠ 盘口上「已经挂出去」——挂盘口是下一节的事。</p><p><strong>5.本节怎样算结束</strong></p><table tabindex="0"><thead><tr><th>结果</th><th>接下来</th></tr></thead><tbody><tr><td>成功</td><td>可以进入「进订单簿」；等待中的上游可收到受理成功</td></tr><tr><td>失败</td><td>停在这里：不进盘口、资金没有成功占用</td></tr></tbody></table><h3 id="两个容易混的点" tabindex="-1">两个容易混的点 <a class="header-anchor" href="#两个容易混的点" aria-label="Permalink to &quot;两个容易混的点&quot;">​</a></h3><ul><li><strong>恢复历史挂单</strong>（撮合重启把未完结单摆回盘口）走初始化链路，不会在本节再扣一遍可用。见<a href="/pages/070505">撮合初始化链路</a>。</li><li>用户感觉「一下单就成交了」：工程上仍是先做完本节占用与建单，再进下一节比价；只是两步挨得很紧。</li></ul><h2 id="_3-下单-进入订单簿-·-成交或挂剩" tabindex="-1">3. 下单：进入订单簿 · 成交或挂剩 <a class="header-anchor" href="#_3-下单-进入订单簿-·-成交或挂剩" aria-label="Permalink to &quot;3. 下单：进入订单簿 · 成交或挂剩&quot;">​</a></h2><p>本节带着已建好的委托进该交易对订单簿：能撮就连续成交，否则把剩余挂在盘口（或已完全成交则新单不留簿）。</p><p>买档价高优先，卖档价低优先；同价先进先出。</p><h3 id="比价怎么走" tabindex="-1">比价怎么走 <a class="header-anchor" href="#比价怎么走" aria-label="Permalink to &quot;比价怎么走&quot;">​</a></h3><p><strong>买单（限价）</strong></p><ol><li>剩余量 = 本单数量。</li><li>反复取<strong>卖盘最优价</strong>：若最优卖价 ≤ 本单限价且仍有剩余，则在该价与卖方队列成交。</li><li>一档吃完再试下一档，直到价不满足或量用尽。</li><li>若仍有剩余 → <strong>限价挂入买盘</strong>；若无剩余 → <strong>整单出簿 / 完全成交</strong>（新单不留盘口）。</li></ol><p>**卖单（限价）**对称：吃买盘，条件为最优买价 ≥ 本单限价；剩余挂入卖盘。</p><h3 id="一笔成交时大致做什么" tabindex="-1">一笔成交时大致做什么 <a class="header-anchor" href="#一笔成交时大致做什么" aria-label="Permalink to &quot;一笔成交时大致做什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th>说明</th></tr></thead><tbody><tr><td>成交量</td><td>双方剩余量的较小值</td></tr><tr><td>成交价</td><td>按买卖限价与参考价规则确定</td></tr><tr><td>委托状态</td><td>有剩余 → 部分成交；剩余为 0 → 完全成交（可移出热委托）</td></tr><tr><td>账务</td><td>解冻占用、划转资产、计手续费（撮合内存账本；展开见<a href="/pages/070512">手续费计费落地</a>）</td></tr><tr><td>落缓冲</td><td>账户、委托、成交明细写入 Redis</td></tr><tr><td>外发意向</td><td>深度、最新成交、成交通知进入发送队列（图末统一外发）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>结果</th><th>订单簿</th><th>委托</th></tr></thead><tbody><tr><td>价不满足 / 无对手</td><td>整单挂簿</td><td>未成交</td></tr><tr><td>部分成交</td><td>剩余挂簿</td><td>部分成交</td></tr><tr><td>全部成交</td><td>新单不留簿</td><td>完全成交</td></tr></tbody></table><p>教学数字见<a href="/pages/0701#complete">业务概述 · 案例</a>。</p><p>用户可能感觉「一下单就成交」：工程上仍是<strong>先完成上一节冻结建单，再进入本节进簿</strong>；同步返回往往在上一节成功时已发出。</p><h2 id="_4-撤单-出簿解冻" tabindex="-1">4. 撤单：出簿解冻 <a class="header-anchor" href="#_4-撤单-出簿解冻" aria-label="Permalink to &quot;4. 撤单：出簿解冻&quot;">​</a></h2><p>撤单走图上右支，与下单共用处理链，<strong>不解冻在进链瞬间做，而在出簿时做</strong>。<br> 委托侧如何查单、调撮合，见<a href="/pages/070503">撤单主流程</a>；本节只写引擎内动作。</p><h3 id="关键动作" tabindex="-1">关键动作 <a class="header-anchor" href="#关键动作" aria-label="Permalink to &quot;关键动作&quot;">​</a></h3><ol><li>若委托仍在簿上：按剩余量扣深度，从价位队列移除。</li><li>未成交占用 <strong>冻结 → 可用</strong>（买退计价币，卖退基础币）。</li><li>委托置为已撤销，更新 Redis 缓冲并移出热委托。</li></ol><p>已完全成交或不在簿上的单，撤单可能无效或拒绝。撤单与成交争同一剩余量时，以引擎内串行结果为准——不能按客户端点击瞬间的旧快照解冻。语义见<a href="/pages/0701#complete">业务概述 · 案例</a>；路径见<a href="/pages/070503">撤单主流程</a>。</p><h2 id="_5-深度-成交外发与异步落库" tabindex="-1">5. 深度 / 成交外发与异步落库 <a class="header-anchor" href="#_5-深度-成交外发与异步落库" aria-label="Permalink to &quot;5. 深度 / 成交外发与异步落库&quot;">​</a></h2><p>下单支与撤单支汇合后，实时改账仍以撮合内存为准；推送与落库走旁路：</p><table tabindex="0"><thead><tr><th>通道</th><th>作用</th></tr></thead><tbody><tr><td>深度 / 成交 MQ</td><td>挂单、成交扣档、撤单引起的档位与最新成交；另有业务成交通知</td></tr><tr><td>Redis → MySQL</td><td>账户、委托、成交等增量由后台刷库；终态委托还可进检索</td></tr></tbody></table><p>刷库积压或写 Redis 严重失败时，可能影响整站可写能力——属运行保障，不是单笔下单校验范畴。</p><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对照</th><th>说明</th></tr></thead><tbody><tr><td><a href="/pages/070505">撮合初始化链路</a></td><td>恢复历史未完结委托<strong>摆回</strong>订单簿并开放接单；不是本文的新单比价</td></tr><tr><td><a href="/pages/070502">下单主流程</a> / <a href="/pages/070503">撤单主流程</a></td><td>委托入口；本文从入链起</td></tr><tr><td><a href="/pages/070511">充提改账协同</a></td><td>非交易事件如何改同一热钱包</td></tr><tr><td><a href="/pages/070512">手续费计费落地</a></td><td>成交计费与 <code>paTotal</code> / <code>adTotal</code></td></tr><tr><td><a href="/pages/0701">业务概述</a></td><td>资金教学表；本文不重复演算</td></tr><tr><td><a href="/pages/070509">行情推送流程</a></td><td>展示侧推送；本文只产出外发意向</td></tr><tr><td>热路径依赖</td><td>内存订单簿 + 账户 / 委托缓存；Redis 缓冲；MQ；MySQL 为异步目标</td></tr></tbody></table><p>同组：<a href="/pages/070502">下单主流程</a> · <a href="/pages/070503">撤单主流程</a> · <a href="/pages/070512">手续费计费落地</a> · <a href="/pages/070511">充提改账协同</a> · <a href="/pages/070509">行情推送流程</a> · <a href="/pages/070802">用户币币账户缓存</a></p>',54)])])}const f=e(s,[["render",n]]);export{b as __pageData,f as default};
